mapper.select:
SELECT dg.legal_dong_code FROM ( SELECT CONCAT(hi.sgg_cd, hi.umd_cd) AS legal_dong_code, MIN(CAST(LEFT(hi.sgg_cd, 2) AS UNSIGNED)) AS sido_code, AVG(CAST(hi.latitude AS DECIMAL(12, 8))) AS dong_lat, AVG(CAST(hi.longitude AS DECIMAL(12, 8))) AS dong_lng FROM houseinfos hi
JOIN dongcodes dc ON dc.dong_code = CONCAT(hi.sgg_cd, hi.umd_cd) WHERE hi.latitude IS NOT NULL AND hi.latitude != '' AND hi.longitude IS NOT NULL AND hi.longitude != '' GROUP BY CONCAT(hi.sgg_cd, hi.umd_cd) ) dg JOIN ( /* 시도별 중심 좌표 — 행정코드 기반이므로 좌표 오입력과 무관하게 신뢰 가능 */ SELECT 11 AS sc, 37.5665 AS slat, 126.9780 AS slng UNION ALL SELECT 26, 35.1796, 129.0756 UNION ALL /* 부산 */ SELECT 27, 35.8714, 128.6014 UNION ALL /* 대구 */ SELECT 28, 37.4563, 126.7052 UNION ALL /* 인천 */ SELECT 29, 35.1595, 126.8526 UNION ALL /* 광주 */ SELECT 30, 36.3504, 127.3845 UNION ALL /* 대전 */ SELECT 31, 35.5384, 129.3114 UNION ALL /* 울산 */ SELECT 36, 36.4800, 127.2890 UNION ALL /* 세종 */ SELECT 41, 37.2752, 127.0095 UNION ALL /* 경기 */ SELECT 42, 37.5535, 128.2137 UNION ALL /* 강원 */ SELECT 43, 36.6358, 127.4914 UNION ALL /* 충북 */ SELECT 44, 36.5184, 126.8001 UNION ALL /* 충남 */ SELECT 45, 35.7175, 127.1530 UNION ALL /* 전북 */ SELECT 46, 34.8679, 126.9910 UNION ALL /* 전남 */ SELECT 47, 36.4919, 128.8889 UNION ALL /* 경북 */ SELECT 48, 35.4606, 128.2132 UNION ALL /* 경남 */ SELECT 50, 33.4890, 126.4983 /* 제주 */ ) sido ON dg.sido_code = sido.sc WHERE /* 1단계: 시도 중심점 게이트 — 잘못된 좌표로 인한 엉뚱한 시도 완전 차단 */ (6371 * ACOS(LEAST(1, GREATEST(-1, COS(RADIANS(#{originLat})) * COS(RADIANS(sido.slat)) * COS(RADIANS(sido.slng) - RADIANS(#{originLng})) + SIN(RADIANS(#{originLat})) * SIN(RADIANS(sido.slat)) )))) <= #{radiusKm} + 50 /* 2단계: 동 평균 좌표 정밀 필터 */ AND (6371 * ACOS(LEAST(1, GREATEST(-1, COS(RADIANS(#{originLat})) * COS(RADIANS(dg.dong_lat)) * COS(RADIANS(dg.dong_lng) - RADIANS(#{originLng})) + SIN(RADIANS(#{originLat})) * SIN(RADIANS(dg.dong_lat)) )))) <= #{radiusKm}
AND EXISTS ( SELECT 1 FROM houseinfos price_hi JOIN housedeals price_hd ON price_hd.apt_seq = price_hi.apt_seq WHERE CONCAT(price_hi.sgg_cd, price_hi.umd_cd) = dg.legal_dong_code GROUP BY CONCAT(price_hi.sgg_cd, price_hi.umd_cd) HAVING COUNT(price_hd.no) >= 5
AND SUM(CASE WHEN CAST(REPLACE(COALESCE(price_hd.deal_amount, '0'), ',', '') AS UNSIGNED) <= #{maxPrice} THEN 1 ELSE 0 END) / COUNT(price_hd.no) >= 0.60
) ORDER BY dg.legal_dong_code
